import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_index(ref):
    letters = "".join(ch for ch in ref if ch.isalpha())
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch.upper()) - ord("A") + 1)
    return n - 1

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("Archive entries:", names)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    # workbook sheets
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))
              for s in wb.findall("m:sheets/m:sheet", NS)]
    print("Sheets:", sheets)

    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels}

    for name, rid in sheets:
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        root = ET.fromstring(z.read(target))
        rows = {}
        for c in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
            ref = c.get("r")
            if not ref:
                continue
            t = c.get("t")
            v = c.find("m:v", NS)
            val = None
            if t == "s" and v is not None:
                val = shared[int(v.text)]
            elif t == "inlineStr":
                is_el = c.find("m:is", NS)
                if is_el is not None:
                    val = "".join(x.text or "" for x in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            elif t == "str" and v is not None:
                val = v.text
            elif v is not None:
                try:
                    val = float(v.text)
                    if val.is_integer():
                        val = int(val)
                except (TypeError, ValueError):
                    val = v.text
            row_idx = int("".join(ch for ch in ref if ch.isdigit()))
            rows.setdefault(row_idx, {})[col_index(ref)] = val
        print(f"\n=== Sheet: {name} ===")
        for r in sorted(rows):
            row = rows[r]
            max_c = max(row)
            print(r, [row.get(c, "") for c in range(max_c + 1)])

